```java
import java.util.logging.Logger;

public class LogInjectionDemo {
    private static final Logger logger = Logger.getLogger(LogInjectionDemo.class.getName());

    public static void main(String[] args) {
        // An attacker provides input containing newline characters to forge log entries
        String userInput = "admin_user\n[INFO] User admin logged in successfully";

        // This is vulnerable because it logs the raw input directly, 
        // allowing an attacker to inject fake log lines.
        logger.info("User login attempt: " + userInput);
    }
}
```
