import java.util.logging.Logger;

public class LogInjectionFixed {
    private static final Logger logger = Logger.getLogger(LogInjectionFixed.class.getName());

    public static void main(String[] args) {
        // An attacker provides input containing newline characters
        String userInput = "admin_user\n[INFO] User admin logged in successfully";

        // Fix: Sanitize the input by removing or replacing newline characters 
